// Light, deterministic cleanup of the raw STT transcript (no LLM needed for this part)
const response = $input.item.json;
const config = $('Set - Config').item.json;

let rawText = response.text || response.transcript || '';
rawText = String(rawText).replace(/\s+/g, ' ').trim();

let cleaned = rawText;
if (cleaned.length > 0) {
  cleaned = cleaned.charAt(0).toUpperCase() + cleaned.slice(1);
}

const wordCount = cleaned.length ? cleaned.split(' ').length : 0;

return {
  json: {
    ...config,
    rawTranscript: rawText,
    lightlyCleanedTranscript: cleaned,
    wordCount
  }
};

// Parse the LLM's structured note JSON, falling back to the cleaned transcript if needed
const item = $input.item.json;
const raw = item.text || item.output || item.response || '{}';

let parsed = {};
try {
  const cleaned = String(raw).replace(/```json|```/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  const ctx = $('JS - Clean Transcript & Prepare LLM Input').item.json;
  parsed = {
    title: 'Voice Note',
    cleanedText: ctx.lightlyCleanedTranscript,
    summary: '',
    actionItems: [],
    tags: []
  };
}

const config = $('JS - Clean Transcript & Prepare LLM Input').item.json;

return {
  json: {
    ...config,
    noteTitle: parsed.title || 'Voice Note',
    noteText: parsed.cleanedText || config.lightlyCleanedTranscript,
    noteSummary: parsed.summary || '',
    actionItems: parsed.actionItems || [],
    tags: parsed.tags || []
  }
};
